void GetNamedProperty(v8::Local<v8::Name> name, const v8::PropertyCallbackInfo<v8::Value>& info) {
  v8::Isolate* isolate = info.GetIsolate();
  v8::Local<v8::String> name_str = name->ToString(isolate->GetCurrentContext()).ToLocalChecked();
  LocalDOMWindow* window = ToLocalDOMWindow(info.Holder());
  if (!window || !window->IsAttached()) {
    return;
  }

  Frame* frame = window->GetFrame();
  if (!frame) {
    return;
  }

  Element* element = frame->GetDocument()->getElementById(name_str);
  if (element) {
    info.GetReturnValue().Set(V8PerIsolateData::GetCurrent()->GetDOMWrapper(isolate, element));
    return;
  }

  Node* node = frame->GetDocument()->GetNodeFromNamedItem(name_str);
  if (node) {
    info.GetReturnValue().Set(V8PerIsolateData::GetCurrent()->GetDOMWrapper(isolate, node));
    return;
  }

  // Check for sub-frames
  for (Frame* child : frame->GetChildFrames()) {
    if (child && child->GetDocument()) {
      element = child->GetDocument()->getElementById(name_str);
      if (element) {
        info.GetReturnValue().Set(V8PerIsolateData::GetCurrent()->GetDOMWrapper(isolate, element));
        return;
      }
    }
  }

  // No match found
  info.GetReturnValue().Set(v8::Null(isolate));
}

void GetNamedProperty(v8::Local<v8::Name> name, const v8::PropertyCallbackInfo<v8::Value>& info) {
    v8::Isolate* isolate = info.GetIsolate();
    v8::Local<v8::Value> result;

    if (!name->IsString()) {
        return;
    }

    v8::Local<v8::String> nameStr = name->ToString(isolate->GetCurrentContext()).ToLocalChecked();
    v8::Local<v8::Object> holder = info.Holder();

    LocalDOMWindow* window = ToLocalDOMWindow(holder);
    if (!window || !window->IsAttached()) {
        return;
    }

    Frame* frame = window->GetFrame();
    if (!frame) {
        return;
    }

    Document* document = frame->GetDocument();
    if (!document) {
        return;
    }

    Node* node = document->GetElementById(nameStr);
    if (!node) {
        node = document->GetNamedItem(nameStr);
    }

    if (node) {
        result = node->ToV8Value(isolate);
        info.GetReturnValue().Set(result);
        return;
    }

    ScriptFunction* function = document->GetScriptFunction(nameStr);
    if (function) {
        result = function->GetV8Function(isolate);
        info.GetReturnValue().Set(result);
        return;
    }

    info.GetReturnValue().Set(v8::Null(isolate));
}

void GetNamedProperty(v8::Local<v8::Name> name, const v8::PropertyCallbackInfo<v8::Value>& info) {
  v8::Isolate* isolate = info.GetIsolate();
  LocalDOMWindow* window = ToLocalDOMWindow(info.Holder());
  if (!window || !window->IsAttached()) {
    return;
  }

  String name_str(*v8::String::Cast(*name));
  Node* item = window->document()->getElementById(name_str);
  if (!item) {
    item = window->document()->GetElementNamedItem(name_str);
  }

  if (item) {
    info.GetReturnValue().Set(ToV8(item, isolate));
  }
}

void GetNamedProperty(v8::Local<v8::Name> name, const v8::PropertyCallbackInfo<v8::Value>& info) {
  v8::Isolate* isolate = info.GetIsolate();
  v8::Local<v8::Object> holder = info.Holder();

  // Check if name is a string
  if (!name->IsString()) {
    return;
  }

  v8::Local<v8::String> nameStr = v8::Local<v8::String>::Cast(name);
  v8::String::Utf8Value utf8Name(isolate, nameStr);
  std::string propertyName(*utf8Name);

  // Retrieve the LocalDOMWindow
  LocalDOMWindow* window = ToLocalDOMWindow(holder);
  if (!window || !window->IsAttached()) {
    return;
  }

  // Check for sub-frames and named items
  Frame* frame = window->GetFrame();
  if (frame && frame->IsLocalFrame()) {
    Document* document = frame->GetDocument();
    if (document) {
      Element* element = document->GetElementById(propertyName);
      if (element) {
        v8::Local<v8::Value> v8Element = ToV8(element, holder, isolate);
        if (!v8Element.IsEmpty()) {
          info.GetReturnValue().Set(v8Element);
          return;
        }
      }
    }
  }

  // If nothing found, do not set a return value
}

void GetNamedProperty(v8::Local<v8::Name> name, const v8::PropertyCallbackInfo<v8::Value>& info) {
    v8::Isolate* isolate = info.GetIsolate();
    v8::Local<v8::Object> holder = info.Holder();

    LocalDOMWindow* window = ToLocalDOMWindow(holder);
    if (!window || !window->IsAttachedToFrame())
        return;

    Frame* frame = window->GetFrame();
    if (!frame || !frame->GetDocument())
        return;

    String name_str = v8_string_to_string(name);
    Element* element = frame->GetDocument()->GetElementById(name_str);
    if (!element)
        return;

    v8::Local<v8::Value> value;
    element->Wrap(isolate, &value);
    info.GetReturnValue().Set(value);
}
